CREATE TABLE public.school_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role public.app_role NOT NULL, access_level public.access_level NOT NULL DEFAULT 'basic', status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,user_id));
GRANT SELECT ON public.school_memberships TO authenticated;
GRANT ALL ON public.school_memberships TO service_role;
ALTER TABLE public.school_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_read ON public.school_memberships FOR SELECT TO authenticated USING (user_id=auth.uid() OR private.has_role(auth.uid(),'super_admin'));
CREATE TRIGGER memberships_updated BEFORE UPDATE ON public.school_memberships FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX memberships_user_status ON public.school_memberships(user_id,status,school_id);
CREATE FUNCTION public.validate_membership() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.role='super_admin' OR NEW.access_level='super_administrator' OR NEW.status NOT IN ('active','suspended') THEN RAISE EXCEPTION 'Invalid school membership'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_membership() FROM PUBLIC;
CREATE TRIGGER validate_membership BEFORE INSERT OR UPDATE ON public.school_memberships FOR EACH ROW EXECUTE FUNCTION public.validate_membership();
DO $$ DECLARE sid uuid; BEGIN SELECT id INTO sid FROM public.schools ORDER BY active DESC,created_at LIMIT 1; IF sid IS NULL THEN RAISE EXCEPTION 'Existing records need a configured school'; END IF;
INSERT INTO public.school_memberships(school_id,user_id,role,access_level,status) SELECT sid,p.id,p.role, CASE WHEN p.access_level='super_administrator' THEN 'administrator'::public.access_level ELSE p.access_level END, CASE WHEN p.status='active' THEN 'active' ELSE 'suspended' END FROM public.profiles p WHERE p.role<>'super_admin'; END $$;
CREATE FUNCTION public.active_school_id() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE requested text; sid uuid; uid uuid:=auth.uid(); platform boolean; BEGIN IF uid IS NULL THEN RETURN NULL; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=uid AND status='active') THEN RETURN NULL; END IF; SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role='super_admin') INTO platform; requested:=NULLIF(current_setting('request.headers',true),'')::jsonb->>'x-school-id'; IF requested IS NOT NULL AND requested<>'' THEN BEGIN sid:=requested::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END; IF EXISTS(SELECT 1 FROM public.schools s WHERE s.id=sid AND s.active AND (platform OR EXISTS(SELECT 1 FROM public.school_memberships m WHERE m.user_id=uid AND m.school_id=s.id AND m.status='active'))) THEN RETURN sid; END IF; RETURN NULL; END IF; SELECT s.id INTO sid FROM public.schools s WHERE s.active AND (platform OR EXISTS(SELECT 1 FROM public.school_memberships m WHERE m.user_id=uid AND m.school_id=s.id AND m.status='active')) ORDER BY s.created_at,s.id LIMIT 1; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.active_school_id() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.active_school_id() TO authenticated,service_role;
CREATE FUNCTION public.school_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='super_admin') AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active') THEN 'super_admin' ELSE (SELECT role::text FROM public.school_memberships WHERE user_id=auth.uid() AND school_id=public.active_school_id() AND status='active') END $$;
REVOKE ALL ON FUNCTION public.school_role() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.school_role() TO authenticated,service_role;
DO $$ DECLARE t text; sid uuid; BEGIN SELECT id INTO sid FROM public.schools ORDER BY active DESC,created_at LIMIT 1; FOREACH t IN ARRAY ARRAY['admissions','class_teachers','teaching_assignments','staff_performance','staff_schedules','offer_letters','finance_income','finance_expenses','finance_payroll','student_assessments','student_attendance','student_performance','student_fees','student_exeat','audit_logs'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN school_id uuid REFERENCES public.schools(id)',t); EXECUTE format('UPDATE public.%I SET school_id=$1 WHERE school_id IS NULL',t) USING sid; IF t<>'audit_logs' THEN EXECUTE format('ALTER TABLE public.%I ALTER COLUMN school_id SET NOT NULL',t); END IF; EXECUTE format('ALTER TABLE public.%I ALTER COLUMN school_id SET DEFAULT public.active_school_id()',t); EXECUTE format('CREATE INDEX %I ON public.%I(school_id)',t||'_school_idx',t); END LOOP; UPDATE public.subjects SET school_id=sid WHERE school_id IS NULL; ALTER TABLE public.subjects ALTER COLUMN school_id SET NOT NULL; END $$;
ALTER TABLE public.class_teachers DROP CONSTRAINT class_teachers_class_name_key; ALTER TABLE public.class_teachers ADD UNIQUE(school_id,class_name);
ALTER TABLE public.teaching_assignments DROP CONSTRAINT teaching_assignments_teacher_id_class_name_subject_key; ALTER TABLE public.teaching_assignments ADD UNIQUE(school_id,teacher_id,class_name,subject);
ALTER TABLE public.admissions ADD UNIQUE(school_id,id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['student_assessments','student_attendance','student_performance','student_fees','student_exeat'] LOOP EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY(school_id,admission_id) REFERENCES public.admissions(school_id,id) ON DELETE CASCADE',t,t||'_school_admission_fk'); END LOOP; END $$;
CREATE OR REPLACE FUNCTION private.is_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='super_admin') OR EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=_user_id AND school_id=public.active_school_id() AND status='active' AND role='school_manager') $$;
CREATE OR REPLACE FUNCTION private.staff_teaches_class(_class_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.school_role()='staff' AND EXISTS(SELECT 1 FROM public.teaching_assignments WHERE school_id=public.active_school_id() AND lower(class_name)=lower(_class_name) AND teacher_id=auth.uid()) $$;
CREATE OR REPLACE FUNCTION private.staff_teaches_admission(_admission_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admissions WHERE id=_admission_id AND school_id=public.active_school_id() AND private.staff_teaches_class(class_admitted)) $$;
CREATE FUNCTION public.shares_active_school(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=_user AND school_id=public.active_school_id() AND status='active') $$;
REVOKE ALL ON FUNCTION public.shares_active_school(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.shares_active_school(uuid) TO authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['admissions','class_teachers','teaching_assignments','staff_performance','staff_schedules','offer_letters','finance_income','finance_expenses','finance_payroll','student_assessments','student_attendance','student_performance','student_fees','student_exeat','tenant_settings','school_branding','school_classes','subjects','numbering_settings','numbering_counters','finance_config_sections','finance_reference_items','finance_rules','finance_config_audit','audit_logs'] LOOP EXECUTE format('CREATE POLICY school_isolation ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(school_id=public.active_school_id()) WITH CHECK(school_id=public.active_school_id())',t); END LOOP; END $$;
CREATE POLICY school_directory ON public.schools AS RESTRICTIVE FOR ALL TO authenticated USING(private.has_role(auth.uid(),'super_admin') OR id=public.active_school_id()) WITH CHECK(private.has_role(auth.uid(),'super_admin'));
CREATE POLICY school_profiles ON public.profiles AS RESTRICTIVE FOR ALL TO authenticated USING(id=auth.uid() OR public.shares_active_school(id) OR private.has_role(auth.uid(),'super_admin')) WITH CHECK(id=auth.uid() OR public.shares_active_school(id) OR private.has_role(auth.uid(),'super_admin'));
CREATE POLICY own_identity_update ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING(private.has_role(auth.uid(),'super_admin')) WITH CHECK(private.has_role(auth.uid(),'super_admin'));
CREATE POLICY school_roles_read ON public.user_roles AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.shares_active_school(user_id) OR private.has_role(auth.uid(),'super_admin'));
CREATE POLICY reset_platform_only ON public.password_reset_requests AS RESTRICTIVE FOR ALL TO authenticated USING(private.has_role(auth.uid(),'super_admin')) WITH CHECK(private.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.guard_school_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE linked uuid; BEGIN IF TG_OP='UPDATE' AND NEW.school_id IS DISTINCT FROM OLD.school_id THEN RAISE EXCEPTION 'School ownership cannot be changed'; END IF; IF TG_TABLE_NAME IN ('staff_schedules','staff_performance','finance_payroll') THEN linked:=NEW.staff_id; ELSIF TG_TABLE_NAME IN ('teaching_assignments','class_teachers') THEN linked:=NEW.teacher_id; END IF; IF linked IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=linked AND school_id=NEW.school_id AND status='active') THEN RAISE EXCEPTION 'Person is not an active member of this school'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_school_links() FROM PUBLIC;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['admissions','class_teachers','teaching_assignments','staff_performance','staff_schedules','offer_letters','finance_income','finance_expenses','finance_payroll','student_assessments','student_attendance','student_performance','student_fees','student_exeat'] LOOP EXECUTE format('CREATE TRIGGER school_links BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_school_links()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.get_public_branding_full() RETURNS TABLE(name text,tagline text,logo_url text,primary_color text,accent_color text,established_year text,motto text,language text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(NULLIF(btrim(b.display_name),''),s.name)::text,COALESCE(b.tagline,'')::text,b.logo_url::text,COALESCE(b.primary_color,'')::text,COALESCE(b.accent_color,'')::text,COALESCE(b.established_year,'')::text,COALESCE(b.motto,'')::text,COALESCE(b.language,'en')::text FROM public.schools s LEFT JOIN public.school_branding b ON b.school_id=s.id WHERE (auth.uid() IS NULL OR s.id=public.active_school_id()) ORDER BY s.active DESC,s.created_at LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.get_public_branding() RETURNS TABLE(name text,tagline text,logo_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT f.name,f.tagline,f.logo_url FROM public.get_public_branding_full() f $$;